def _logit(p):
    p = min(max(float(p), 1e-5), 1.0 - 1e-5)
    return math.log(p / (1.0 - p))


class HybridPrototypePAR(nn.Module):
    def __init__(
        self,
        num_attributes=40,
        prototype_dim=256,
        prototype_temperature=0.20,
        prototype_gate_init=0.35,
        prototype_ema_momentum=0.95,
        prototype_ema_mix=0.25,
    ):
        super().__init__()

        self.num_attributes = int(num_attributes)
        self.prototype_dim = int(prototype_dim)
        self.prototype_temperature = float(prototype_temperature)
        self.prototype_ema_momentum = float(prototype_ema_momentum)
        self.prototype_ema_mix = float(prototype_ema_mix)

        base = convnext_tiny(weights=None)
        self.backbone = base
        self.backbone_dim = int(base.classifier[2].in_features)
        self.backbone.classifier[2] = nn.Identity()

        self.global_dropout = nn.Dropout(0.22)
        self.linear_head = nn.Linear(
            self.backbone_dim,
            self.num_attributes,
        )

        self.token_norm = nn.LayerNorm(self.backbone_dim)
        self.token_proj = nn.Linear(
            self.backbone_dim,
            self.prototype_dim,
            bias=False,
        )

        self.attribute_queries = nn.Parameter(
            torch.zeros(
                self.num_attributes,
                self.prototype_dim,
            )
        )

        self.attribute_norm = nn.LayerNorm(
            self.prototype_dim
        )

        self.prototype_pos = nn.Parameter(
            torch.zeros(
                self.num_attributes,
                self.prototype_dim,
            )
        )
        self.prototype_neg = nn.Parameter(
            torch.zeros(
                self.num_attributes,
                self.prototype_dim,
            )
        )

        self.register_buffer(
            "prototype_pos_ema",
            torch.zeros(
                self.num_attributes,
                self.prototype_dim,
            ),
        )
        self.register_buffer(
            "prototype_neg_ema",
            torch.zeros(
                self.num_attributes,
                self.prototype_dim,
            ),
        )
        self.register_buffer(
            "prototype_pos_updates",
            torch.zeros(
                self.num_attributes,
                dtype=torch.long,
            ),
        )
        self.register_buffer(
            "prototype_neg_updates",
            torch.zeros(
                self.num_attributes,
                dtype=torch.long,
            ),
        )

        self.prototype_gate_logits = nn.Parameter(
            torch.full(
                (self.num_attributes,),
                _logit(prototype_gate_init),
                dtype=torch.float32,
            )
        )

    def effective_prototypes(self):
        learned_pos = F.normalize(
            self.prototype_pos,
            dim=-1,
        )
        learned_neg = F.normalize(
            self.prototype_neg,
            dim=-1,
        )
        ema_pos = F.normalize(
            self.prototype_pos_ema,
            dim=-1,
        )
        ema_neg = F.normalize(
            self.prototype_neg_ema,
            dim=-1,
        )

        mix = float(self.prototype_ema_mix)

        pos = F.normalize(
            (1.0 - mix) * learned_pos
            + mix * ema_pos,
            dim=-1,
        )
        neg = F.normalize(
            (1.0 - mix) * learned_neg
            + mix * ema_neg,
            dim=-1,
        )
        return pos, neg

    def forward(self, x):
        fmap = self.backbone.features(x)

        pooled = self.backbone.avgpool(fmap)
        pooled = self.backbone.classifier[0](pooled)
        global_feature = pooled.flatten(1)

        linear_logits = self.linear_head(
            self.global_dropout(global_feature)
        )

        tokens = fmap.permute(
            0,
            2,
            3,
            1,
        ).contiguous()

        tokens = self.token_norm(tokens)
        tokens = self.token_proj(tokens)
        tokens = tokens.flatten(1, 2)

        q = F.normalize(
            self.attribute_queries,
            dim=-1,
        )
        k = F.normalize(
            tokens,
            dim=-1,
        )

        attn_logits = torch.einsum(
            "bnd,cd->bcn",
            k,
            q,
        ) / 0.10

        attn = torch.softmax(
            attn_logits,
            dim=-1,
        )

        features = torch.einsum(
            "bcn,bnd->bcd",
            attn,
            tokens,
        )

        features = self.attribute_norm(
            features
        )
        features = F.normalize(
            features,
            dim=-1,
        )

        pos, neg = self.effective_prototypes()

        pos_sim = torch.einsum(
            "bcd,cd->bc",
            features,
            pos,
        )
        neg_sim = torch.einsum(
            "bcd,cd->bc",
            features,
            neg,
        )

        proto_logits = (
            pos_sim - neg_sim
        ) / max(
            float(self.prototype_temperature),
            1e-4,
        )

        gate = torch.sigmoid(
            self.prototype_gate_logits
        ).reshape(1, -1)

        gate = gate.clamp(
            0.08,
            0.92,
        )

        return (
            (1.0 - gate) * linear_logits
            + gate * proto_logits
        )


def _sanitize_config(config, state):
    config = dict(config or {})

    if "linear_head.weight" in state:
        config["num_attributes"] = int(
            state["linear_head.weight"].shape[0]
        )

    if "attribute_queries" in state:
        config["prototype_dim"] = int(
            state["attribute_queries"].shape[1]
        )

    defaults = {
        "num_attributes": 40,
        "prototype_dim": 256,
        "prototype_temperature": 0.20,
        "prototype_gate_init": 0.35,
        "prototype_ema_momentum": 0.95,
        "prototype_ema_mix": 0.25,
    }

    return {
        key: config.get(key, default)
        for key, default in defaults.items()
    }


class PrototypeRuntime:
    def __init__(self, bundle_path):
        self.device = torch.device(
            "cuda"
            if torch.cuda.is_available()
            else "cpu"
        )

        bundle = _safe_torch_load(
            bundle_path,
            map_location="cpu",
        )

        self.attribute_names = list(
            bundle["attribute_names"]
        )

        if len(self.attribute_names) != 40:
            raise ValueError(
                "Submission bundle must contain exactly 40 attributes."
            )

        self.name_to_index = {
            name: i
            for i, name in enumerate(self.attribute_names)
        }

        self.image_height = int(
            bundle.get("image_height", 288)
        )
        self.image_width = int(
            bundle.get("image_width", 144)
        )
        self.tta = str(
            bundle.get("tta", "flip")
        )

        threshold_logits = torch.as_tensor(
            bundle["threshold_logits"],
            dtype=torch.float32,
        ).reshape(-1)

        if threshold_logits.numel() != 40:
            raise ValueError(
                "Expected exactly 40 threshold logits."
            )

        self.threshold_logits = (
            threshold_logits
            .reshape(1, -1)
            .to(self.device)
        )

        self.transform = transforms.Compose([
            transforms.Resize(
                (
                    self.image_height,
                    self.image_width,
                ),
                interpolation=(
                    transforms.InterpolationMode.BICUBIC
                ),
            ),
            transforms.ToTensor(),
            transforms.Normalize(
                [0.485, 0.456, 0.406],
                [0.229, 0.224, 0.225],
            ),
        ])

        members = list(
            bundle.get("members", [])
        )

        if not members:
            raise ValueError(
                "Submission bundle contains no ensemble members."
            )

        self.models = []
        self.weights = []

        for item in members:
            weight = float(
                item.get("weight", 0.0)
            )

            if weight <= 0.0:
                item["state_dict"] = None
                continue

            state = item.get("state_dict")

            if not isinstance(state, dict):
                raise TypeError(
                    "Ensemble member has no valid state_dict."
                )

            cfg = _sanitize_config(
                item.get(
                    "prototype_config",
                    {},
                ),
                state,
            )

            model = HybridPrototypePAR(
                **cfg,
            )

            model.load_state_dict(
                state,
                strict=True,
            )

            item["state_dict"] = None
            del state

            model = model.to(
                self.device
            ).eval()

            self.models.append(model)
            self.weights.append(weight)

        del members
        del bundle
        gc.collect()

        if self.device.type == "cuda":
            torch.cuda.empty_cache()

        if not self.models:
            raise RuntimeError(
                "All ensemble members have zero weight."
            )

        weight_sum = sum(self.weights)

        if (
            not math.isfinite(weight_sum)
            or weight_sum <= 0
        ):
            raise RuntimeError(
                "Invalid ensemble weights."
            )

        self.weights = [
            float(w / weight_sum)
            for w in self.weights
        ]

    def _open_image(self, path):
        with Image.open(path) as image:
            return self.transform(
                image.convert("RGB")
            )

    def _requested_indices(self, attribute_names):
        requested = list(attribute_names)

        if len(requested) != 40:
            raise ValueError(
                f"Expected 40 attributes, got {len(requested)}"
            )

        unknown = [
            x
            for x in requested
            if x not in self.name_to_index
        ]

        if unknown:
            raise KeyError(
                "Challenge requested unknown attributes: "
                + ", ".join(unknown)
            )

        return [
            self.name_to_index[x]
            for x in requested
        ]

    def _model_logits(self, model, x):
        if self.device.type == "cuda":
            with torch.autocast(
                device_type="cuda",
                dtype=torch.float16,
            ):
                logits = model(x)

                if self.tta == "flip":
                    logits_flip = model(
                        torch.flip(
                            x,
                            dims=[3],
                        )
                    )
                    logits = 0.5 * (
                        logits
                        + logits_flip
                    )
        else:
            logits = model(x)

            if self.tta == "flip":
                logits_flip = model(
                    torch.flip(
                        x,
                        dims=[3],
                    )
                )
                logits = 0.5 * (
                    logits
                    + logits_flip
                )

        return logits.float()

    @torch.inference_mode()
    def _predict_tensor(self, x):
        total = None

        for model, weight in zip(
            self.models,
            self.weights,
        ):
            logits = (
                self._model_logits(
                    model,
                    x,
                )
                * float(weight)
            )

            total = (
                logits
                if total is None
                else total + logits
            )

        if total is None:
            raise RuntimeError(
                "No active ensemble members."
            )

        probs = torch.sigmoid(
            total - self.threshold_logits
        )

        return torch.nan_to_num(
            probs.float(),
            nan=0.5,
            posinf=1.0,
            neginf=0.0,
        ).clamp(0.0, 1.0)

    def predict_samples(
        self,
        samples,
        micro_batch_size=MICRO_BATCH_SIZE,
    ):
        rows = []

        for start in range(
            0,
            len(samples),
            int(micro_batch_size),
        ):
            chunk = samples[
                start:start + int(micro_batch_size)
            ]

            images = torch.stack([
                self._open_image(
                    str(sample["image_path"])
                )
                for sample in chunk
            ]).to(
                self.device,
                non_blocking=True,
            )

            probs = (
                self._predict_tensor(images)
                .cpu()
            )

            for i, sample in enumerate(chunk):
                indices = self._requested_indices(
                    sample["attribute_names"]
                )

                row = probs[
                    i,
                    indices,
                ].tolist()

                if len(row) != 40:
                    raise RuntimeError(
                        "Prediction row does not contain 40 values."
                    )

                if not all(
                    math.isfinite(float(x))
                    for x in row
                ):
                    raise RuntimeError(
                        "Prediction row contains NaN/Inf."
                    )

                if not all(
                    0.0 <= float(x) <= 1.0
                    for x in row
                ):
                    raise RuntimeError(
                        "Prediction outside [0, 1]."
                    )

                rows.append([
                    float(x)
                    for x in row
                ])

            del images
            del probs

        return rows


