        raise TypeError(
            "Each sample must be a dictionary."
        )

    required = (
        "image_path",
        "attribute_names",
    )

    missing = [
        key
        for key in required
        if key not in sample
    ]

    if missing:
        raise KeyError(
            f"Submission sample is missing keys: {missing}"
        )

    if len(sample["attribute_names"]) != 40:
        raise ValueError(
            "Expected exactly 40 attribute_names."
        )


def predict_image(sample):
    _validate_sample(sample)

    model = _ensure_model()

    return model.predict_samples(
        [sample],
        micro_batch_size=1,
    )[0]


def predict_batch(samples):
    if not isinstance(
        samples,
        (list, tuple),
    ):
        raise TypeError(
            "predict_batch expects a list/tuple of samples."
        )

    if len(samples) == 0:
        return []

    for sample in samples:
        _validate_sample(sample)

    model = _ensure_model()

    return model.predict_samples(
        list(samples),
        micro_batch_size=MICRO_BATCH_SIZE,
    )
